static void subMatrices(Matriz M,
                        LinkedList<Matriz>L){

    L.clear();

    for(int i=0;i<M.fil();i++)
    for(int j=0;j<M.col();j++)
    for(int a=i;a<M.fil();a++)
    for(int b=j;b<M.col();b++)

        L.add(subMatriz(M,i,j,a,b));
}

